'use strict';
(async()=>{const $=id=>document.getElementById(id);let renderer,token=0;const cache=new Map();
try{renderer=new SourceMeshView($('diagram'));}catch(e){$('status').textContent=e.message;return;}
async function load(id){if(!cache.has(id))cache.set(id,fetch('../system-source/catalogue/'+id+'.json').then(r=>{if(!r.ok)throw Error('Could not load '+id);return r.json();}).then(m=>{if(m.schema!=='obtp-source-mesh/1'||m.units!=='mm'||!m.assets?.length)throw Error('Unexpected source geometry '+id);renderer.register(m);return m;}).catch(e=>{cache.delete(id);throw e;}));return cache.get(id);}
async function render(){const stamp=++token;const items=OBTPCatalogue.assembly($('layer').value);$('status').textContent='Loading source geometry…';renderer.setScene([]);$('schedule').replaceChildren();try{await Promise.all([...new Set(items.map(i=>i.block))].map(load));if(stamp!==token)return;renderer.setScene(items,{explode:Number($('explode').value)/100});for(const row of OBTPCatalogue.counts(items)){const tr=document.createElement('tr');for(const value of [row.id,OBTPCatalogue.parts.find(p=>p.id===row.id).role,row.count]){const td=document.createElement('td');td.textContent=value;tr.append(td);}$('schedule').append(tr);}$('status').textContent=items.length+' component instances · ready';window.OBTPStudioV2={items,renderer};}catch(e){if(stamp===token)$('status').textContent=e.message;}}
$('layer').onchange=render;$('explode').oninput=()=>{$('amount').textContent=$('explode').value+'%';renderer.explode=Number($('explode').value)/100;renderer.draw();};$('reset').onclick=()=>{ $('explode').value=0;$('amount').textContent='0%';renderer.explode=0;renderer.reset();};await render();})();
